// Harness entry. Loads the REAL game code (every .ts under game/assets/scripts) and the REAL Main.scene.
// Only two things are swapped: the engine bootstrap (harness-boot.ts) and the AssetLoader (fetch instead of resources).
import { js, deserialize, director, assetManager, ImageAsset, SceneAsset, input, Input, EventTouch, view, TTFFont, AudioClip } from 'cc';
import { bootEngine } from './harness-boot';
import { setLoader } from '../../../game/assets/scripts/AssetLoader';
// Generated by harness/run.mjs: imports every game script and lists { file, cid, mod } for scripts with a .meta.
import { scripts } from 'harness:game-scripts';

const RES = '/game/resources/';
type Touch = { id: number; x: number; y: number; type: string };
const H: any = ((window as any).__harness = { ready: false, error: null, touches: [] as Touch[], logs: [] as string[] });

function aliasScriptClasses(): void {
  // The editor registers each script's class under the compressed uuid of its .meta (scene files use that id).
  for (const s of scripts) {
    const base = s.file.replace(/^.*\//, '').replace(/\.ts$/, '');
    for (const v of Object.values(s.mod)) {
      if (typeof v === 'function' && js.getClassName(v as any) === base) js.setClassAlias(v as any, s.cid);
    }
  }
}

async function main(): Promise<void> {
  setLoader({
    async json<T>(path: string): Promise<T> {
      const r = await fetch(RES + path + '.json');
      if (!r.ok) throw new Error(`json ${path}: HTTP ${r.status}`);
      return (await r.json()) as T;
    },
    image(path: string): Promise<ImageAsset> {
      return new Promise((ok, fail) => assetManager.loadRemote<ImageAsset>(RES + path + '.png', (e, a) => (e ? fail(e) : ok(a))));
    },
    font(path: string): Promise<TTFFont> {
      return new Promise((ok, fail) => assetManager.loadRemote<TTFFont>(RES + path + '.ttf', (e, a) => (e ? fail(e) : ok(a))));
    },
    audio(path: string, ext: string): Promise<AudioClip> {
      return new Promise((ok, fail) => assetManager.loadRemote<AudioClip>(RES + path + ext, (e, a) => (e ? fail(e) : ok(a))));
    },
  });
  await bootEngine('/engine/builtin-2d-effects.json');
  aliasScriptClasses();
  const sceneJson = await (await fetch('/game/scenes/Main.scene')).json();
  const sceneAsset = deserialize(sceneJson, undefined) as SceneAsset;
  director.runSceneImmediate(sceneAsset);
  // Diagnostics only: records touches as the game sees them (UI coordinates, origin bottom-left).
  const rec = (type: string) => (e: EventTouch) => {
    const p = e.getUILocation();
    H.touches.push({ id: e.getID(), x: Math.round(p.x), y: Math.round(p.y), type });
  };
  input.on(Input.EventType.TOUCH_START, rec('start'));
  input.on(Input.EventType.TOUCH_MOVE, rec('move'));
  input.on(Input.EventType.TOUCH_END, rec('end'));
  H.stats = () => {
    const d = (director.root as any).device;
    return { drawCalls: d.numDrawCalls, tris: d.numTris, instances: d.numInstances, frames: director.getTotalFrames() };
  };
  // Design/UI coordinate (origin bottom-left, y up) -> CSS pixel in the page.
  H.uiToCss = (x: number, y: number) => {
    const vp = view.getViewportRect();
    const dpr = window.devicePixelRatio || 1;
    const sx = view.getScaleX(), sy = view.getScaleY();
    const visOrigin = view.getVisibleOrigin();
    const fh = (document.getElementById('GameCanvas') as HTMLCanvasElement).getBoundingClientRect().height;
    const px = ((x - visOrigin.x) * sx + vp.x) / dpr;
    const py = ((y - visOrigin.y) * sy + vp.y) / dpr;
    return { x: px, y: fh - py };
  };
  H.visible = () => ({ origin: view.getVisibleOrigin(), size: view.getVisibleSize(), design: view.getDesignResolutionSize() });
  H.ready = true;
}

main().catch((e) => {
  H.error = String(e && e.stack ? e.stack : e);
  console.error(e);
});
